const P=id=>document.getElementById('p-'+id),pen=document.documentElement.lang==='en',PT=(vi,en)=>pen?en:vi,PF=(x,n=2)=>x==null?'—':x.toLocaleString(pen?'en-US':'vi-VN',{maximumFractionDigits:n});let psyInputs=[{t:26,kind:'rh',value:50},{t:35,kind:'rh',value:65}],psyActive=0,psyStates=[],psyMixed=null,psyYmax=.03;const plot={x:62,y:28,w:770,h:455};
const psyNames={rh:[PT('Độ ẩm tương đối','Relative humidity'),'%',0,100],wb:[PT('Nhiệt độ bầu ướt','Wet-bulb temperature'),'°C',-100,60],dp:[PT('Điểm sương / sương giá','Dew / frost point'),'°C',-100,60],w:[PT('Dung ẩm','Humidity ratio'),'g/kgda',0,1000],h:[PT('Entanpi riêng','Specific enthalpy'),'kJ/kgda',-30,1500]};
function psyLoad(){const a=psyInputs[psyActive];P('dry').value=a.t;P('kind').value=a.kind;P('value').value=a.value;psyLabel();document.querySelectorAll('#p-tabs button').forEach(b=>b.classList.toggle('selected',+b.dataset.point===psyActive));}
function psyLabel(){const a=psyNames[P('kind').value];document.querySelector('label[for="p-value"]').textContent=a[0];P('value').nextElementSibling.textContent=a[1];P('value').min=a[2];P('value').max=a[3];}
function psyUpdate(){const pressure=+P('pressure').value*1000;psyStates=psyInputs.map(a=>{try{return psyState(+a.t,a.kind,+a.value,pressure);}catch{return null;}});const r=psyStates[psyActive];P('error').hidden=!!r;P('error').textContent=PT('Trạng thái không hợp lệ hoặc vượt bão hòa. Bầu khô −20…60 °C, áp suất 60…110 kPa; bầu ướt/điểm sương không vượt bầu khô.','Invalid or supersaturated state. Dry bulb −20…60 °C, pressure 60…110 kPa; wet bulb and dew point cannot exceed dry bulb.');const values=r?[[PT('Độ ẩm tương đối','Relative humidity'),PF(r.rh)+'%'],[PT('Dung ẩm','Humidity ratio'),PF(r.w*1000)+' g/kgda'],[PT('Entanpi riêng','Specific enthalpy'),PF(r.h)+' kJ/kgda'],[PT('Bầu ướt','Wet bulb'),PF(r.wb)+' °C'],[PT('Điểm sương / sương giá','Dew / frost point'),PF(r.dp)+(r.dp==null?'':' °C')],[PT('Thể tích riêng','Specific volume'),PF(r.v,3)+' m³/kgda'],[PT('Khối lượng riêng khí ẩm','Moist-air density'),PF(r.rho,3)+' kg/m³']]:[];P('properties').innerHTML=values.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');psyProcess();psyChart();psyTable();window.HVACPsychroReport?.ready();}
function psyProcess(){psyMixed=null;const [a,b]=psyStates,m=+P('mass').value,f=+P('fraction').value/100;if(!a||!b||!Number.isFinite(m)||!Number.isFinite(f)||m<=0||f<0||f>1){P('process-results').innerHTML='<p>'+PT('Cần hai trạng thái hợp lệ, lưu lượng > 0 và tỷ lệ hòa trộn từ 0–100%.','Two valid states, positive mass flow and a mixing fraction of 0–100% are required.')+'</p>';return;}let message='';try{psyMixed=psyMix(a,b,f);}catch{message=PT('Hỗn hợp vượt bão hòa. Cần mô hình ngưng tụ riêng.','The mixture is supersaturated. A condensation model is required.');}const heat=m*(b.h-a.h),water=m*(b.w-a.w)*1000;P('process-results').innerHTML=`<div class="psy-loads"><div><span>${PT('Công suất trao đổi nhiệt A → B','Heat transfer rate A → B')}</span><strong>${heat>=0?'+':''}${PF(heat)} <small>kW</small></strong><p>${heat>=0?PT('Cần bổ sung nhiệt','Heat added'):PT('Cần lấy nhiệt ra','Heat removed')}</p></div><div><span>${PT('Lưu lượng ẩm thêm/bớt A → B','Moisture addition/removal rate A → B')}</span><strong>${water>=0?'+':''}${PF(water)} <small>g/s</small></strong><p>${water>=0?PT('Bổ sung ẩm','Moisture added'):PT('Loại ẩm','Moisture removed')}</p></div></div><p class="psy-mix-note">${psyMixed?PT('Hỗn hợp M: ','Mixed state M: ')+PF(psyMixed.t)+' °C · '+PF(psyMixed.rh)+'% RH · '+PF(psyMixed.h)+' kJ/kgda':message}</p>`;}
function psyTable(){const entries=[['A',psyStates[0]],['B',psyStates[1]],['M',psyMixed]];P('table').innerHTML=entries.map(([name,r])=>'<tr><td><strong>'+name+'</strong></td>'+ (r?[r.t,r.rh,r.w*1000,r.h,r.wb,r.dp,r.v].map((v,i)=>'<td>'+PF(v,i===6?3:2)+'</td>').join(''):'<td colspan="7">'+PT('Chưa có trạng thái hợp lệ','No valid state')+'</td>')+'</tr>').join('');}
function psyChart(){const pressure=+P('pressure').value*1000;if(!Number.isFinite(pressure)||pressure<60000||pressure>110000){P('chart').innerHTML='';return;}const valid=psyStates.filter(Boolean);psyYmax=Math.max(.03,Math.ceil(Math.max(0,...valid.map(r=>r.w),psyMixed?.w||0)*1.18/.01)*.01);const X=t=>plot.x+(t+20)/80*plot.w,Y=w=>plot.y+plot.h-w/psyYmax*plot.h;let contents='',sat='';for(let t=-20;t<=60;t+=.25)sat+=(t===-20?'M':'L')+X(t)+','+Y(Math.min(psyYmax,psyWs(t,pressure)));const region=`M${X(-20)},${Y(0)}L${X(60)},${Y(0)}L${X(60)},${Y(Math.min(psyYmax,psyWs(60,pressure)))} `+Array.from({length:321},(_,i)=>{const t=60-i*.25;return'L'+X(t)+','+Y(Math.min(psyYmax,psyWs(t,pressure)));}).join('')+'Z';contents+=`<defs><clipPath id="psy-domain"><path d="${region}"/></clipPath><linearGradient id="psy-bg" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ecfaf6"/><stop offset="1" stop-color="#fff"/></linearGradient></defs><rect x="${plot.x}" y="${plot.y}" width="${plot.w}" height="${plot.h}" fill="url(#psy-bg)"/><g clip-path="url(#psy-domain)">`;
for(let t=-20;t<=60;t+=5)contents+=`<line x1="${X(t)}" x2="${X(t)}" y1="${Y(0)}" y2="${plot.y}" stroke="#e0e9ec"/>`;for(let w=0;w<=psyYmax;w+=psyYmax/10)contents+=`<line x1="${plot.x}" x2="${X(60)}" y1="${Y(w)}" y2="${Y(w)}" stroke="#e0e9ec"/>`;
function line(fn,color,dash='',width=1){let d='',drawing=false;for(let t=-20;t<=60;t+=.25){const w=fn(t);if(Number.isFinite(w)&&w>=0&&w<=psyYmax&&w<=psyWs(t,pressure)+1e-9){d+=(drawing?'L':'M')+X(t)+','+Y(w);drawing=true;}else drawing=false;}return`<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;}
if(P('rh').checked)for(let rh=10;rh<100;rh+=10){contents+=line(t=>{const pv=psySat(t)*rh/100;return .621945*pv/(pressure-pv);},'#8abbaf','',1);let t=55;while(t>-15&&.621945*psySat(t)*rh/100/(pressure-psySat(t)*rh/100)>psyYmax*.95)t-=1;const w=.621945*psySat(t)*rh/100/(pressure-psySat(t)*rh/100);contents+=`<text x="${X(t)}" y="${Y(w)-4}" fill="#50998b" font-size="11">${rh}%</text>`;}
if(P('h').checked)for(let h=-20;h<=200;h+=10)contents+=line(t=>(h-1.006*t)/(2501+1.86*t),'#bda084','5 5');if(P('wb').checked)for(let wb=-15;wb<=45;wb+=5)contents+=line(t=>t>=wb?psyWwet(t,wb,pressure):NaN,'#7c9ccb','2 4');if(P('volume').checked)for(let v=.65;v<=1.6;v+=.05)contents+=line(t=>(v*pressure/(287.042*(t+273.15))-1)/1.607858,'#b4a1c4','7 4');contents+=`</g><path d="${sat}" fill="none" stroke="#138e78" stroke-width="2.5"/>`;
for(let t=-20;t<=60;t+=10)contents+=`<text x="${X(t)}" y="${Y(0)+23}" text-anchor="middle" fill="#728892" font-size="12">${t}</text>`;for(let i=0;i<=10;i++){const w=psyYmax*i/10;contents+=`<text x="${X(60)+12}" y="${Y(w)+4}" fill="#728892" font-size="12">${PF(w*1000,1)}</text>`;}contents+=`<text x="${plot.x+plot.w/2}" y="${Y(0)+56}" text-anchor="middle" fill="#496a77" font-size="14">${PT('Nhiệt độ bầu khô','Dry-bulb temperature')} (°C)</text><text x="${X(60)+8}" y="16" fill="#496a77" font-size="12">W (g/kgda)</text>`;
if(psyStates.every(Boolean)){const[a,b]=psyStates;contents+=`<line x1="${X(a.t)}" y1="${Y(a.w)}" x2="${X(b.t)}" y2="${Y(b.w)}" stroke="#476575" stroke-width="2" stroke-dasharray="6 4"/>`;}
[['A',psyStates[0],'#05a68a'],['B',psyStates[1],'#f09843'],['M',psyMixed,'#8662c4']].forEach(([label,r,color],i)=>{if(r)contents+=`<g><circle cx="${X(r.t)}" cy="${Y(r.w)}" r="${i===psyActive?8:6}" fill="${color}" stroke="white" stroke-width="3"/><text x="${X(r.t)+11}" y="${Y(r.w)-11}" fill="${color}" font-size="15" font-weight="700">${label}</text></g>`;});P('chart').innerHTML=contents;P('chart-pressure').textContent=PF(pressure/1000,3)+' kPa';P('chart-note').textContent=PT('RH: xanh lá · Entanpi riêng: nâu · Bầu ướt: xanh lam · Thể tích riêng: tím.','RH: green · Enthalpy: brown · Wet bulb: blue · Specific volume: purple.');}
document.querySelectorAll('#p-tabs button').forEach(b=>b.onclick=()=>{psyActive=+b.dataset.point;psyLoad();psyUpdate();});['dry','value'].forEach(id=>P(id).addEventListener('input',()=>{psyInputs[psyActive]={t:+P('dry').value,kind:P('kind').value,value:+P('value').value};psyUpdate();}));P('kind').onchange=()=>{const r=psyStates[psyActive],kind=P('kind').value;P('value').value=r?({rh:r.rh,wb:r.wb,dp:r.dp??-100,w:r.w*1000,h:r.h}[kind]).toFixed(5):kind==='rh'?50:0;psyInputs[psyActive]={t:+P('dry').value,kind,value:+P('value').value};psyLabel();psyUpdate();};['pressure','mass','fraction'].forEach(id=>P(id).addEventListener('input',psyUpdate));['rh','h','wb','volume'].forEach(id=>P(id).onchange=psyChart);
P('chart').addEventListener('click',e=>{const svg=P('chart'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const point=pt.matrixTransform(svg.getScreenCTM().inverse()),t=(point.x-plot.x)/plot.w*80-20,w=(plot.y+plot.h-point.y)/plot.h*psyYmax,pressure=+P('pressure').value*1000;if(t< -20||t>60||w<0||w>psyYmax||w>psyWs(t,pressure)||!Number.isFinite(pressure))return;psyInputs[psyActive]={t:+t.toFixed(2),kind:'w',value:+(w*1000).toFixed(4)};psyLoad();psyUpdate();});P('reset').onclick=()=>{psyInputs=[{t:26,kind:'rh',value:50},{t:35,kind:'rh',value:65}];psyActive=0;P('pressure').value=101.325;P('mass').value=1;P('fraction').value=50;psyLoad();psyUpdate();};psyLoad();psyUpdate();
